DELETE FROM public.digest_activities
WHERE user_activity_id = {{data_table.triggeredRow.id}}
AND {{
  ["p.solovev@sdgroup.ai"].map((e) => e.toLowerCase()).includes((appsmith.user.email || "").toLowerCase())
    ? "TRUE"
    : "user_activity_id IN (SELECT id FROM public.user_activities WHERE user_id IN (SELECT DISTINCT user_id FROM public.digests WHERE user_name ILIKE '%" + (appsmith.user.email || "").split("@")[0].replace(/'/g, "''") + "%'))"
}};

DELETE FROM public.user_activities
WHERE id = {{data_table.triggeredRow.id}}
AND {{
  ["p.solovev@sdgroup.ai"].map((e) => e.toLowerCase()).includes((appsmith.user.email || "").toLowerCase())
    ? "TRUE"
    : "user_id IN (SELECT DISTINCT user_id FROM public.digests WHERE user_name ILIKE '%" + (appsmith.user.email || "").split("@")[0].replace(/'/g, "''") + "%')"
}};
